@page "/recipes/{CuisineId:int}"
@using sv_d511063cce1441f3b396a26af384b85b.Services
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject RecipeService RecipeService
@inject NavigationManager Nav
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private bool _disposed;

    private IReadOnlyList<Recipe> DisplayedRecipes
    {
        get
        {
            if (_recipes is null) return [];
            return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes.OrderByDescending(r => r.Id).ToList()
                : _recipes.OrderBy(r => r.Id).ToList();
        }
    }

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Sort changed but cuisine didn't — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }
        _loadCts = new CancellationTokenSource();
        var ct = _loadCts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;
        var cuisineId = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, ct);

            if (ct.IsCancellationRequested) return;

            _recipes = results;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Expected when cuisine changed or component disposed — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            if (!ct.IsCancellationRequested)
            {
                _error = "The request timed out. Please try again.";
                _recipes = null;
            }
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            if (!ct.IsCancellationRequested)
            {
                _error = "Something went wrong loading the recipes. Please try again.";
                _recipes = null;
            }
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        _disposed = true;

        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }
}

